components.css:
.ds-btn-primary { background: #2563eb; color: #fff; border: 1px solid #2563eb; border-radius: 4px; padding: 0.5rem 1rem; font-size: 0.9rem; font-family: inherit; cursor: pointer; transition: background 0.2s ease, color 0.2s ease; }
.ds-btn-primary:hover:not(:disabled) { background: #1e40af; border-color: #1e40af; }
.ds-btn-primary:disabled { opacity: 0.6; cursor: default; }
.ds-btn-primary:focus-visible { outline: 2px solid #2563eb; outline-offset: 2px; }

.ds-btn-secondary { background: #fff; color: #374151; border: 1px solid #d1d5db; border-radius: 4px; padding: 0.5rem 1rem; font-size: 0.9rem; font-family: inherit; cursor: pointer; transition: color 0.15s ease, border-color 0.15s ease; }
.ds-btn-secondary:hover:not(:disabled) { background: #f3f4f6; }
.ds-btn-secondary:disabled { opacity: 0.6; cursor: default; }
.ds-btn-secondary:focus-visible { outline: 2px solid #2563eb; outline-offset: 2px; }

.ds-btn-danger { background: transparent; color: #dc2626; border: 1px solid #fca5a5; border-radius: 4px; padding: 0.25rem 0.5rem; font-size: 0.8rem; font-family: inherit; cursor: pointer; transition: background 0.2s ease; }
.ds-btn-danger:hover { background: #fef2f2; }
.ds-btn-danger:focus-visible { outline: 2px solid #dc2626; outline-offset: 2px; }

.ds-field { display: flex; flex-direction: column; font-size: 0.8rem; color: #374151; font-family: inherit; }
.ds-input { margin-top: 0.25rem; padding: 0.5rem; border: 1px solid #d1d5db; border-radius: 4px; font-size: 0.9rem; font-family: inherit; background: #fff; color: #374151; }
.ds-input:focus, .ds-input:focus-visible { outline: 2px solid #2563eb; outline-offset: 1px; border-color: #2563eb; }

.ds-card { background: #fff; border: 1px solid #e5e7eb; border-radius: 8px; padding: 1rem; font-family: inherit; }
.ds-card h2 { font-size: 1.1rem; font-weight: 600; margin: 0 0 0.75rem; }
.ds-card__lede { margin: 0; font-size: 0.85rem; color: #6b7280; }

.ds-tag { display: inline-flex; align-items: center; gap: 0.25rem; background: #eff6ff; color: #2563eb; padding: 0.125rem 0.375rem; border-radius: 3px; font-size: 0.8rem; font-weight: 500; font-family: inherit; }
.ds-tag__remove { background: none; border: none; color: #2563eb; cursor: pointer; padding: 0; font-size: 1rem; line-height: 1; opacity: 0.6; font-family: inherit; }
.ds-tag__remove:hover { opacity: 1; }
.ds-tag__remove:focus-visible { outline: 2px solid #2563eb; outline-offset: 1px; }

.ds-tabs { display: flex; border-bottom: 1px solid #e5e7eb; font-family: inherit; }
.ds-tab { flex: 1; padding: 0.75rem 1rem; text-align: center; text-decoration: none; color: #6b7280; font-weight: 500; border-bottom: 2px solid transparent; margin-bottom: -1px; transition: color 0.15s ease, border-color 0.15s ease; font-family: inherit; }
.ds-tab:hover { color: #374151; }
.ds-tab.is-active { color: #2563eb; border-bottom-color: #2563eb; }
.ds-tab:focus-visible { outline: 2px solid #2563eb; outline-offset: -2px; }
@media (pointer: coarse) { .ds-tab { min-height: 44px; } }

.ds-banner { display: flex; align-items: center; justify-content: space-between; gap: 0.5rem; width: 100%; box-sizing: border-box; padding: 0.6rem 1rem; background: #eff6ff; border-bottom: 1px solid #bfdbfe; font-family: inherit; }
.ds-banner__status { display: flex; flex-direction: column; gap: 0.125rem; min-width: 0; }
.ds-banner__method { font-weight: 600; color: #1e40af; }
.ds-banner__time { color: #1e40af; font-size: 0.85rem; }
.ds-banner__action { background: #2563eb; color: #fff; border: 1px solid #2563eb; border-radius: 4px; padding: 0.25rem 0.5rem; font-size: 0.8rem; font-family: inherit; cursor: pointer; flex-shrink: 0; transition: background 0.2s ease, border-color 0.2s ease; }
.ds-banner__action:hover:not(:disabled) { background: #1e40af; border-color: #1e40af; }
.ds-banner__action:disabled { opacity: 0.6; cursor: default; }
.ds-banner__action:focus-visible { outline: 2px solid #2563eb; outline-offset: 2px; }
@media (pointer: coarse) { .ds-banner__action { min-height: 44px; } }

.ds-error { display: flex; align-items: center; justify-content: space-between; gap: 0.5rem; margin: 0; padding: 0.5rem 1rem; background: #fef2f2; color: #b91c1c; font-size: 0.85rem; font-family: inherit; border-bottom: 1px solid #fecaca; }
.ds-error__text { min-width: 0; }
.ds-error__dismiss { background: #fff; color: #b91c1c; border: 1px solid #fca5a5; border-radius: 4px; padding: 0.25rem 0.5rem; font-size: 0.8rem; font-family: inherit; cursor: pointer; flex-shrink: 0; }
.ds-error__dismiss:hover { background: #fef2f2; }
.ds-error__dismiss:focus-visible { outline: 2px solid #dc2626; outline-offset: 2px; }

.ds-movement { display: flex; align-items: center; gap: 0.75rem; font-size: 0.9rem; font-family: inherit; padding: 0.5rem 0; border-bottom: 1px solid #f3f4f6; }
.ds-movement__arrow { font-weight: 600; text-align: center; width: 1.25rem; }
.ds-movement__arrow--income { color: #16a34a; }
.ds-movement__arrow--expense { color: #dc2626; }
.ds-movement__arrow--transfer { color: #6b7280; }
.ds-movement__category { font-weight: 500; }
.ds-movement__meta { font-size: 0.8rem; color: #6b7280; }
.ds-movement__amount { margin-left: auto; font-weight: 600; }
.ds-movement__amount--income { color: #16a34a; }
.ds-movement__amount--expense { color: #dc2626; }
